(404, '350/PEMA/VI/2025', 'y8Hyu0Ai92v6H6MlwjhON2SQgHSdZyGJmM8PWMtq', 'Bank Central Asia', 'Pembayaran gaji karyawan bulan Juni', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2025-06-24 02:01:00', '2025-06-24 02:01:00');
INSERT INTO `surats` (`id`, `nomor_surat`, `no_document`, `kepada`, `perihal`, `j_lampiran`, `jenis_lampiran`, `file_lampiran`, `isi_surat`, `tembusans`, `id_divisi`, `submitted_by`, `submitted_current_position`, `sign_by`, `bahasa`, `created_at`, `updated_at`) VALUES
(405, '351/PEMA/VI/2025', 'HcGEpQTvHus8V5280e97Y5cpMJXZFsaNiqhyeKwB', 'Direktur Utama Wema Agro Sdn. Bhd', 'Undangan Rapat Kolaborasi dan Sinergi dengan PT Pembangunan Aceh (Perseroda)', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<ol>\n<li>PT Pembangunan Aceh (Perseroda) adalah Badan Usaha Milik Aceh (BUMA) yang didirikan berdasarkan amanat Qanun Aceh Nomor 16 Tahun 2017, dimana 100% sahamnya dimiliki oleh Pemerintah Aceh dengan usaha utama di bidang minyak dan gas bumi, pertambangan, ketenagalistrikan, industri, perdagangan, konstruksi, agrobisnis, lingkungan, perikanan, properti, transportasi dan pariwisata untuk memberdayakan sumber daya milik Pemerintah Aceh dalam rangka pengembangan ekonomi Aceh, mendorong percepatan investasi, memperluas lapangan kerja serta dapat memberikan dampak yang signifikan untuk meningkatkan Pendapatan Asli Aceh (PAA).</li>\n<li>Sehubungan dengan surat Wema Agro Sdn. Bhd nomor WA/089/25 tanggal 18 Juni 2025 perihal Rencana Investasi di Sabang, Aceh kepada Bapak Gubernur Aceh. Dapat kami sampaikan bahwa PT PEMA (Perseroda) tertarik dengan profil Wema Agro Sdn. Bhd dalam minat investasi diberbagai sektor untuk kolaborasi dan sinergi yang menguntungkan kedua belah pihak.</li>\n<li>Berkaitan hal tersebut di atas, kami bermaksud mengundang Bapak/Ibu untuk dapat hadir pada:\n<table style=\"border-collapse: collapse; width: 100%; border: 0px; height: 127.875px;\">\n<tbody>\n<tr style=\"height: 31.9688px;\">\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 16.8344%;\">Hari / Tanggal</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.28728%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 80.8783%;\">Kamis / 10 Juli 2025</td>\n</tr>\n<tr style=\"height: 31.9688px;\">\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 16.8344%;\">Pukul</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.28728%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 80.8783%;\">10.00 WIB - Selesai</td>\n</tr>\n<tr style=\"height: 31.9688px;\">\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 16.8344%;\">Tempat</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.28728%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 80.8783%;\">Ruang Rapat Kantor PT PEMA (Perseroda)</td>\n</tr>\n<tr style=\"height: 31.9688px;\">\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 16.8344%;\">Agenda</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.28728%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 80.8783%;\">Pertemuan dan Diskusi terkait Kerja Sama pada beberapa Projek Potensial&nbsp;</td>\n</tr>\n</tbody>\n</table>\n</li>\n<li style=\"text-align: justify;\">Besar harapan kami agar dapat terjalin kerja sama yang baik antara PT PEMA (Perseroda) dengan Wema Agro Sdn. Bhd.</li>\n</ol>\n<p style=\"text-align: justify;\">Demikian yang dapat kami sampaikan, atas perhatian dan kerjasamanya kami ucapkan terima kasih.</p>', '', 15, '202103032', 'Staf Migas dan EBTKE', '0001', 'id', '2025-06-24 02:41:52', '2025-06-24 02:41:52'),
(406, '352/PEMA/VI/2025', 'hBeQwWnfb8BGuI5DjOAJOz4CUKvx0wg9oGg25LBW', 'Bank Syariah Indonesia', 'Pembayaran Kompensasi Pph 21 Tahun 2024', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2025-06-24 04:35:21', '2025-06-24 04:35:21'),
(407, '353/PEMA/IV/2025', 'EWkD6PkP8ph8pOkUkC2sJDP3sclIkHVsH4h8bsy5', 'Bank Aceh Syariah', 'Pembayaran Kompensasi Pph 21 Karyawan/ti Tahun 2024', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2025-06-24 04:41:34', '2025-06-24 04:41:34'),
(408, '354/PEMA/VI/2025', 'jfveZcWGDh4cGUQZpA6mUOudc2yNmKU2rP1nISDl', 'Bank Tabungan Negara', 'Pembayaran Kompensasi Pph 21 Karyawan/ti Tahun 2024', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>Pengambilan Nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2025-06-24 04:42:10', '2025-06-24 04:42:10'),
(409, '355/PEMA/VI/2025', 'h8dV98FUjkqzP5OhREV9Ntt3d2LnAnjdZL7pQ099', 'General Manager PT Pelindo Multi Terminal Malahayati', 'Permohonan Biaya Dan Dokumentasi Loading Cangkang Kelapa Sawit Via Pelabuhan Malahayati', 0, 'Eks', NULL, '<p><span lang=\"IN\">Dengan</span><span lang=\"EN-US\"> H</span><span lang=\"IN\">ormat,</span></p>\n<ol>\n<li><span lang=\"EN-US\">Sehubungan dengan rencana pengiriman cangkang kelapa sawit dari <em>stockpile </em>melalui Pelabuhan Malahayati Krueng Raya Aceh Besar dengan kuantitas 25.000 ton/trip menggunakan <em>Mother Vessel</em> (MV), kami dari PT Pembangunan Aceh (Perseroda) memohon kepada pihak PT Pelindo Malahayati untuk dapat memberikan harga biaya sewa lahan dan biaya&nbsp;<em>loading </em>yang diperlukan.</span></li>\n<li><span lang=\"EN-US\">Berkaitan dengan hal tersebut di atas, kami juga berharap dapat dilampirkan dokumentasi terkait proses bongkar muat di pelabuhan PT Pelindo Malahayati &nbsp;khususnya <em>loading </em>cangkang kelapa sawit/ekspor tanah (pozzolan) sebagai referensi bagi kami dalam perencanaan logistik.</span></li>\n<li><span lang=\"EN-US\">Kami sangat mengharapkan bantuan dan kerja sama dari PT Pelindo Malahayati untuk dapat memberikan harga dan dokumentasi proses <em>loading</em>. Besar harapan kami agar permohonan ini dapat dipenuhi segera.</span></li>\n</ol>\n<p><span lang=\"EN-US\">Demikian surat permohonan ini kami sampaikan, atas perhatian dan kerjasama yang baik kami ucapkan terima kasih.</span></p>', '', 13, '202103032', 'Staf Migas dan EBTKE', '011', 'id', '2025-06-24 08:11:02', '2025-06-24 08:11:02'),
(410, '356/PEMA/VI/2025', 'FP4mwIjswZLvbz34xdViFGAKnJsSqaCBkE0IQp5u', 'Direktur Utama PT Pupuk Iskandar Muda (PIM)', 'Permohonan Perubahan Status Pelabuhan Untuk Mendukung Kegiatan Bisnis PT Pembangunan Aceh (Perseroda)', 0, 'Eks', NULL, '<p><span lang=\"IN\">Dengan</span><span lang=\"EN-US\"> H</span><span lang=\"IN\">ormat,</span></p>\n<ol>\n<li><span lang=\"EN-US\">Sehubungan dengan pengembangan bisnis PT PEMA (Perseroda) di bidang perdagangan komoditi, serta dalam upaya pemanfaatan potensi bisnis yang berada di wilayah Provinsi Aceh, PT PEMA (Perseroda) berencana untuk melakukan ekspor cangkang kelapa sawit ke luar negeri agar dapat memberikan dampak yang signifikan untuk meningkatkan Pendapatan Asli Aceh (PAA) melalui PT PEMA (Perseroda).</span></li>\n<li><span lang=\"EN-US\">Berdasarkan hal tersebut di atas, melalui surat ini kami menyampaikan permohonan kepada Bapak Direktur Utama PT PIM untuk dapat memberikan dukungan dengan memberikan izin pemanfaatan dari terminal khusus di wilayah PT PIM, Krueng Geukueh agar dapat diutilisasi menjadi pelabuhan umum terbatas untuk PT PEMA (Perseroda) dalam pengiriman cangkang kelapa sawit, kopi dan komoditi lainnya ke luar negeri.</span></li>\n<li><span lang=\"EN-US\">Menimbang saat ini Pelabuhan ex AAF/ Pelabuhan Iskandar Muda Industrial Area (IMIA) yang ada di Krueng Geukueh hanya memilki kapasitas maksimal 15.000 MT, sementara permintaan pasar untuk komoditi cangkang kelapa sawit sebanyak 25.000 MT. Maka dari itu kegiatan ekspor cangkang kelapa sawit hanya dapat dilakukan jika menggunakan terminal khusus di PT PIM.</span></li>\n</ol>\n<p><span lang=\"EN-US\">Demikian permohonan ini kami sampaikan, atas dukungan dan pertimbangan Bapak kami ucapkan terima kasih.</span></p>', '', 13, '202103032', 'Staf Migas dan EBTKE', '0001', 'id', '2025-06-24 09:18:07', '2025-06-24 09:18:07'),
(411, '357/PEMA/VI/2025', '4M2Md8OwziHiX826kUNcDKDCFzQV9FeacW9pvdko', 'Bapak Kepala Badan Pengelola Migas Aceh (BPMA)', 'Permohonan Pengelolaan Wilayah Kerja \"South Block A\"', 1, 'Eks', 'lampiran/2025/357.pdf', '<p>Dengan Hormat,</p>\n<p>Sehubungan dengan pengakhiran Kontrak Kerja Sama Wilayah Kerja \"South Block A\" pada tanggal 27 Januari 2023, maka dapat kami sampaikan sebagai berikut:</p>\n<ol>\n<li>Berdasarkan Pasal 39 Peraturan Pemerintah Nomor 23 Tahun 2015, menyebutkan bahwa Wilayah Kerja yang dikembalikan oleh Kontraktor dapat ditawarkan terlebih dahulu kepada Badan Usaha Milik Daerah (BUMD) sebelum dinyatakan menjadi Wilayah Terbuka, dengan mempertimbangkan program kerja, kemampuan teknis dan keuangan BUMD, sepanjang saham BUMD 100% (seratus persen) dimiliki oleh Pemerintah Aceh.</li>\n<li>PT Pembangunan Aceh (Perseroda) sebagai BUMD yang 100% sahamnya dimiliki oleh Pemerintah Aceh telah mendapatkan rekomendasi Pengelolaan Wilayah Kerja \"South Block A\" dari Gubernur Aceh sesuai dengan surat Nomor 500.10.7.1/18880 tanggal 24 Desember 2024. (terlampir)</li>\n<li>Dalam rangka meningkatkan Pendapatan Asli Aceh dan pengembangan perekonomian Aceh serta untuk meningkatkan kesejahteraan rakyat Aceh, PT PEMA (Perseroda) berminat mengelola Wilayah Kerja \"South Block A\" tersebut yang telah diakhiri Kontrak Kerjasamanya oleh Renco Elang Energy Pte. Ltd.&nbsp;</li>\n<li>Sehubungan dengan hal-hal tersebut, kami memohon kepada Bapak Kepala BPMA untuk dapat mempelajari proposal teknis atas blok yang kami minati tersebut dan memberikan persetujuan sebagaimana hal yang dimaksud di atas.</li>\n</ol>\n<p>Demkian permohonan ini kami sampaikan, atas perhatiannya kami ucapkan terima kasih.</p>', '', 14, '202103032', 'Staf Migas dan EBTKE', '0001', 'id', '2025-06-24 09:28:15', '2025-06-24 09:28:15'),
(412, '358/PEMA/VI/2025', 'eXRUHirYqAwuITE1opV5uW25sgAP9373KjOCQMpl', 'Bapak Kepala Dinas Lingkungan Hidup Kota Langsa', 'Pernyataan Terkait Sanksi Administratif Berupa Paksaan Pemerintah Tanpa Disertai Denda Administratif Kepada PT Pembangunan Aceh', 1, 'Eks', 'lampiran/2025/358.pdf', '<p style=\"text-align: justify;\">Dengan Hormat,</p>\n<p style=\"text-align: justify;\">Sehubungan dengan Keputusan Walikota Langsa Nomor 121/660/2025 Tanggal 17&nbsp;Februari 2025 Tentang Penerapan Sanksi Administratif Berupa Paksaan Pemerintah&nbsp;Tanpa Disertai Denda Administratif Kepada PT Pembangunan Aceh (Diterima oleh PT&nbsp;Pembangunan Aceh pada Tanggal 07 Maret 2025).</p>\n<p style=\"text-align: justify;\">Berkaitan dengan hal tersebut di atas PT Pembangunan Aceh menyampaikan jawaban&nbsp;terkait Paksaan Pemerintah, yaitu:</p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li style=\"text-align: justify;\">Melaksanakan upaya pengelolaan dan pemantauan lingkungan hidup berupa :\n<ol>\n<li style=\"text-align: justify;\">Wajib melakukan Pemantauan Kualitas Udara Ambien;</li>\n<li style=\"text-align: justify;\">Wajib melakukan Pemantauan Tingkat Kebauan;</li>\n<li style=\"text-align: justify;\">Wajib melakukan Pemantauan Kebisingan; dan</li>\n<li style=\"text-align: justify;\">Wajib melakukan Pemantauan Air Limbah, Air Permukaan dan Air Laut.<br><br></li>\n</ol>\nTelah dilaksanakan dan hasil pelaksanaannya telah dilaporkan dalam Laporan UKL-UPL Semester I Tahun 2024 dan Laporan UKL-UPL Semester II Tahun 2024. Dokumen ini juga sudah diinput kedalam akun SIMPEL Kementerian Lingkungan Hidup dan Kehutanan (KLHK) milik PT Pembangunan Aceh.</li>\n<li>Wajib melaporkan Pelaksanaan Upaya Pengelolaan Lingkungan &ndash; Upaya Pemantauan Lingkungan (UKL-UPL) kepada Dinas Lingkungan Hidup Kota Langsa dan Kementerian Lingkungan Hidup dan Kehutanan setiap 6 (enam) bulan sekali;&nbsp;<br>Laporan UKL-UPL Semester I 2024 sudah diserahkan kepada Dinas Lingkungan Hidup Kota Langsa pada 26 Maret 2025. Untuk Laporan UKL-UPL Semester II 2024 sudah diserahkan kepada Dinas Lingkungan Hidup Kota Langsa pada 21 April 2025. Untuk Laporan UKL-UPL Semester I Tahun 2025 akan diserahkan paling lambat di bulan Juli 2025.</li>\n<li style=\"text-align: justify;\">Melaksanakan Kewajiban Penyelenggaraan Perlindungan dengan Pengelolaan Mutu Air Berupa :\n<ol>\n<li>Wajib memiliki penanggung jawab pengendalian pencemaran air yang memiliki&nbsp;sertiﬁkat kompetensi;</li>\n<li>Wajib memiliki operator instalasi pengolahan air limbah yang memiliki sertiﬁkat kompetensi;<br>PT PEMA saat ini telah memiliki penanggung jawab pengendalian pencemaran air (PPPA) atas nama Qausar Andrean yang bersertiﬁkasi Badan Nasional Sertiﬁkasi Profesi (BNSP)(dokumen terlampir).&nbsp;</li>\n<li>PT PEMA saat ini telah memiliki operator instalasi pengolahan air limbah (POPAL) atas nama Muhammad Jarir yang bersertiﬁkasi Badan Nasional Sertiﬁkasi Profesi (BNSP) (dokumen terlampir).</li>\n<li>Wajib melaporkan kewajiban pengendalian pencemaran air pada tiap&nbsp;semester;</li>\n<li>Wajib melakukan pengukuran air limbah sesuai dengan ketentuan pada&nbsp;Persetujuan Teknis Pemenuhan Baku Mutu Air Limbah Nomor 660/394/2023;<br>Telah dilaksanakan dan hasil pelaksanaannya telah dilaporkan dalam Laporan UKL-UPL Semester I Tahun 2024 dan Laporan UKL-UPL Semester II Tahun 2024. Dokumen ini juga sudah diinput kedalam akun SIMPEL Kementerian Lingkungan Hidup dan Kehutanan (KLHK) milik PT Pembangunan Aceh.</li>\n<li>Menyesuaikan titik koordinat penaatan dengan kondisi di lapangan;<br>Akan disesuaikan pada Revisi Dokumen Pengendalian Lingkungan Hidup (DPLH)&nbsp; untuk tahun 2025 dengan target penyelesaian pada Juli 2025.</li>\n<li>Wajib melakukan pemantauan setiap bulan;<br>PT PEMA telah melakukan pengambilan sampel pada Kolam IPAL 3 dan 4 untuk dilakukan uji lab pada Gedung UPT Laboratorium Terpadu USK untuk bulan April, Mei, dan Juni 2025 dan menunggu hasil Lab diperkirakan pada Minngu kedua Bulan Juli.</li>\n<li>Air limbah wajib seluruhnya masuk ke IPAL;<br>Sudah dilakukan penambahan <em>concrete blocking</em> agar air limpasan tidak lagi&nbsp;mengalami <em>overﬂow</em> ke laut dan seluruhnya masuk ke dalam IPAL.</li>\n<li>Proses pengolahan air limbah wajib dilakukan sesuai dengan Persetujuan Teknis Pemenuhan Baku Mutu Air Limbah Nomor 660/394/2023;</li>\n<li>Wajib melakukan uji laboratorium baku mutu air parit/drainase dan melakukan pengolahan air limbah agar tidak melebihi baku mutu yang telah ditentukan; dan</li>\n<li>Wajib mengolah air limbah secara efektif sehingga air limbah yang dimanfaatkan memenuhi baku mutu.<br>Telah dilaksanakan dan hasil pelaksanaannya telah dilaporkan dalam Laporan UKL-UPL Semester I Tahun 2024 dan Laporan UKL-UPL Semester II Tahun 2024. Dokumen ini juga sudah diinput kedalam akun SIMPEL Kementerian Lingkungan Hidup dan Kehutanan (KLHK) milik PT Pembangunan Aceh.&nbsp;<br>PT PEMA telah menyerahkan dokumen Standar Teknis Pemenuhan Baku Mutu Air Limbah Operasi Sulfur di Pelabuhan Kuala Langsa &nbsp;kepada DLH Kota Langsa pada tanggal 03 Juni 2024 serta menunggu hasil pemeriksaan oleh DLH Kota Langsa untuk dijadikan dasar koreksi dokumen tersebut.<br>PT PEMA telah melakukan pengambilan sampel pada Kolam IPAL 3 dan 4 untuk dilakukan uji lab pada Gedung UPT Laboratorium Terpadu USK untuk bulan April, Mei, dan Juni 2025 dan menunggu hasil Lab diperkirakan pada Minngu kedua Bulan Juli.</li>\n</ol>\n</li>\n<li>Melaksanakan upaya perlindungan dan pengelolaan mutu udara sebagai berikut :\n<ol>\n<li>Wajib melakukan pemantauan kualitas udara ambien untuk parameter TSP&nbsp;dilakukan selama 24 jam;<br>Telah dilaksanakan dan hasil pelaksanaannya telah dilaporkan dalam Laporan UKL-UPL Semester I Tahun 2024 dan Laporan UKL-UPL Semester II Tahun 2024. Dokumen ini juga sudah diinput kedalam akun SIMPEL Kementerian Lingkungan Hidup dan Kehutanan (KLHK) milik PT Pembangunan Aceh.</li>\n<li>Wajib membuat dan melaporkan pelaksanaan pemantauan kualitas udara&nbsp;setiap semester kepada Dinas Lingkungan Hidup dan Kehutanan Aceh, Dinas&nbsp;Lingkungan Hidup Kota Langsa dan Kementerian Lingkungan Hidup melalui&nbsp;SIMPEL.<br>Telah melakukan registrasi akun SIMPEL Kementerian Lingkungan Hidup dan Kehutanan (KLHK) atas nama PT Pembangunan Aceh. Adapun dokumen Pemantauan yang sudah diinput adalah Laporan UKL-UPL Semester II Tahun 2023, &nbsp;Laporan UKL-UPL Semester I Tahun 2024 dan Laporan UKL-UPL Semester II Tahun 2024 (Bukti Screenshoot Akun SIMPEL terlampir).</li>\n</ol>\n</li>\n<li>Melaksanakan kewajiban pengelolaan Limbah Bahan Berbahaya dan Beracun (Limbah B3) berupa :</li>\n</ol>\n<ol>\n<li style=\"text-align: justify;\">Wajib melakukan penyimpanan Limbah B3 di tempat penyimpanan Limbah B3,&nbsp;dan memiliki Bangunan Penyimpanan Limbah B3; (Sudah dilakukan) (Foto Terlampir)</li>\n<li style=\"text-align: justify;\">Wajib memiliki rincian teknis penyimpanan Limbah B3 yang dimuat dalam Persetujuan Lingkungan bagi penghasil Limbah B3 dari Usaha dan/atau kegiatan wajib UKL-UPL;<br>Akan disesuaikan pada Revisi Dokumen Pengendalian Lingkungan Hidup (DPLH) untuk tahun 2025 dengan target penyelesaian pada Juli 2025.</li>\n<li style=\"text-align: justify;\">Wajib melakukan identiﬁkasi Limbah B3 yang dihasilkan;</li>\n<li style=\"text-align: justify;\">Wajib menyusun dan menyampaikan Laporan penyimpanan Limbah B3 kepada Dinas Lingkungan Hidup dan Kehutanan Aceh, Dinas Lingkungan Hidup Kota Langsa dan Kementerian Lingkungan Hidup dan Kehutanan; dan</li>\n<li style=\"text-align: justify;\">Wajib melakukan pencatatan nama dan jumlah B3 yang dihasilkan.<br>Sudah dilakukan identiﬁkasi limbah B3 dan dilaporakan kepada &nbsp;ke Dinas Lingkungan Hidup Kota Langsa untuk periode Maret, April, dan Mei 2025 (dokumen terlampir).&nbsp;</li>\n</ol>\n<p style=\"text-align: justify;\">Demikian surat ini kami sampaikan. Atas perhatian dan kerja sama yang baik kami&nbsp;ucapkan terima kasih.</p>', '', 16, '202106034', 'Staf Teknikal dan Operasi (Migas dan EBTKE)', '003', 'id', '2025-06-24 10:21:36', '2025-06-25 09:24:55'),
(413, '359/PEMA/VI/2025', 'xCg9NeL0EUM4gX6prJcap0qrGlYurx1F0MK7nPZM', 'bsi', 'penerbitan depo', 0, 'Eks', NULL, '<p>Dengan Hormat</p>', '', 11, '202107040', 'Staf Keuangan', '0001', 'id', '2025-06-25 04:11:05', '2025-06-25 04:11:05'),
