(577, '522/PEMA/IX/2025', 'IdYkPDHtSG5UyWtPWsNTefitZowBEq5sVDNxJeXM', 'Bank Tabungan Negara', 'Pembayaran Gaji Bulan September 2025', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2025-09-24 02:16:28', '2025-09-24 02:16:28'),
