(920, '40/PEMA/I/2026', 'aM393tLb8NN4DUyQNzsZWrud31RmOXgYJrO8zIPd', 'Kepala Kejaksaan Negeri Banda Aceh', 'Donor Darah', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2026-01-14 10:17:08', '2026-01-14 10:17:08'),
(921, '41/PEMA/I/2026', 'EBXGo6HUok9xB5p8lvhAagqZR5lHwpYmwhtC4U37', 'Kepala Dinas Kebudayaan dan Pariwisata Aceh', 'Donor Darah', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>pengembilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2026-01-14 10:17:39', '2026-01-14 10:17:39'),
(922, '42/PEMA/I/2026', 'VxwRhw0dNsXInhuNeadYvNq4EhrnEvw0uVK88IGg', 'Dinas Pendidikan Kota Banda Aceh', 'Donor Darah', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2026-01-14 10:23:53', '2026-01-14 10:23:53'),
(923, '43/PEMA/I/2026', 'X25Mhrwm1xviUPvZ0yU5qHkVFmZAkvF4yUDd4zED', 'BANK SYARIAH INDONESIA', 'Permohonan Blokir Saldo Rekening', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<p>Sehubungan dengan kepentingan pengamanan dan pengendalian keuangan perusahaan, bersama ini kami mengajukan permohonan pemblokiran saldo rekening pada PT Bank Syariah Indonesia Tbk terhadap beberapa rekening sebagai berikut:</p>\n<ol>\n<li style=\"line-height: 1.4;\">PT Pema Global Servis<br>No. Rekening: 1909999207 (KC Luengbata)<br>No. Rekening: 1909999304 (KC BD Aceh Diponegoro)</li>\n<li style=\"line-height: 1.4;\">Tridaya Pasifik KSO<strong><br></strong>No. Rekening: 1308888831 ((KCP Luengbata)</li>\n<li style=\"line-height: 1.4;\">PGS Dinar KSO<br>No. Rekening: 1909997107 (KC Luengbata</li>\n<li style=\"line-height: 1.4;\">Sumatera Noble Coffee KSO<br>No. Rekening: 9999962634 (KC Takengon)</li>\n</ol>\n<p style=\"line-height: 1.4;\">Permohonan pemblokiran saldo rekening dimaksud kami ajukan sampai dengan adanya pemberitahuan lebih lanjut secara tertulis dari kami, guna mendukung proses pengamanan administrasi, evaluasi internal, serta tindak lanjut manajemen atas rekening-rekening tersebut.</p>\n<p style=\"line-height: 1;\">Sebagai bahan pendukung, kami siap melengkapi dokumen tambahan apabila diperlukan sesuai dengan ketentuan dan prosedur yang berlaku di PT Bank Syariah Indonesia Tbk.</p>\n<p style=\"line-height: 1;\">Demikian permohonan ini kami sampaikan. Atas perhatian dan kerja sama yang baik, kami ucapkan terima kasih.</p>', '', 11, '202308073K', 'Staf Keuangan', '003', 'id', '2026-01-15 08:55:53', '2026-01-15 08:56:22'),
(924, '44/PEMA/I/2026', 'oVGlHCeotnrjk3lkq6sBJ3RqGlgRYcjgi2nl51eY', 'BPJS Kota Banda Aceh', 'Usulan Penonaktifan Kepesertaan BPJS Kesehatan', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>Pengambilan Nomor Surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '0001', 'id', '2026-01-15 09:40:11', '2026-01-15 09:40:11'),
(925, '45/PEMA/I/2026', '4lGudEo9U56ixpMU9CL8MPmY1AY1c07njUk1fTDB', 'Citaglobal Berhad', 'Dukungan Bantuan Bencana Banjir di Aceh', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<p>Ambil nomor</p>', '', 16, '202106034', 'Staf Teknikal dan Operasi (Migas dan EBTKE)', '003', 'id', '2026-01-17 10:30:52', '2026-01-17 10:30:52');
INSERT INTO `surats` (`id`, `nomor_surat`, `no_document`, `kepada`, `perihal`, `j_lampiran`, `jenis_lampiran`, `file_lampiran`, `isi_surat`, `tembusans`, `id_divisi`, `submitted_by`, `submitted_current_position`, `sign_by`, `bahasa`, `created_at`, `updated_at`) VALUES
(926, '46/PEMA/I/2026', 'c6TXqW6UwG11emtxGWTZrHVwf3KLkbOM6Ul82Jnq', 'Hotel Kyriad Muraya', 'Guarantee Letter', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p><span lang=\"IN\">Dengan ini kami sampaikan permohonan pemesanan ruang rapat dengan kapasitas 15 orang untuk digunakan rapat oleh PT Pembangunan Aceh (Perseroda) pada tanggal 19 Januari 2026 dengan jenis paket sebagai berikut&nbsp;</span></p>\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\"><colgroup><col style=\"width: 13.777%;\"><col style=\"width: 52.8316%;\"><col style=\"width: 33.3043%;\"></colgroup>\n<tbody>\n<tr>\n<td style=\"text-align: center;\"><strong>No</strong></td>\n<td style=\"text-align: center;\"><strong>Paket</strong></td>\n<td style=\"text-align: center;\"><strong>Jumlah</strong></td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">1</td>\n<td style=\"text-align: center;\">Ruang Meeting Banda Half Day (1x Coffee Break &amp; 1x Dinner)</td>\n<td style=\"text-align: center;\">15 Pax</td>\n</tr>\n</tbody>\n</table>\n<p><span lang=\"IN\">Sehubungan dengan hal tersebut di atas, untuk segala biaya mohon dapat ditagihkan ke kantor PT PEMA (Perseroda) yang beralamat Rumah Budaya, Jl. Tgk. H. Mohd. Daud Beureuh, Kec. Kuta Alam, Kota Banda Aceh 23121 atau dapat menghubungi ke staf PT PEMA<strong> Sdr. Gibran (082211558548) dengan estimasi waktu pembayaran maksimal 3 (tiga) hari kerja setelah dokumen/ berkas tagihan diterima.&nbsp; </strong></span></p>\n<p><span lang=\"IN\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></p>\n<p><span lang=\"IN\">Demikian yang dapat kami sampaikan atas perhatian dan kerjasamanya kami ucapkan terima kasih.</span></p>', '', 20, '202412106K', 'Staf Umum', '202508121K', 'id', '2026-01-19 04:06:14', '2026-01-19 08:05:55'),
(927, '47/PEMA/I/2026', 'm9xMdPqDvAu0gg1iwozSMf3pjFYDbAWwj86ryfFH', 'Kepala Dinas Pertanian dan Perkebunan', 'Permohonan Pandangan dan Arahan Terkait Rencana Pengembangan Perkebunan Durian', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<p>Dalam rangka mendukung pengembangan sektor agroindustri serta peningkatan nilai tambah komoditas pertanian daerah, PT Pembangunan Aceh (Perseroda) saat ini sedang menjajaki rencana pengembangan perkebunan durian skala komersial, dengan konsep penggunaan bibit unggul serta orientasi pasar ekspor untuk hasil pertaniannya.</p>\n<p>Sehubungan dengan rencana tersebut, kami memandang perlu untuk memperoleh pandangan, masukan, serta arahan teknis dan regulasi dari Dinas Pertanian dan Perkebunan Provinsi Aceh, khususnya terkait hal-hal sebagai berikut:&nbsp;</p>\n<ol>\n<li>Ketentuan dan standar penanaman durian, baik dari aspek teknis budidaya, kesesuaian lahan, maupun standar praktik pertanian yang dianjurkan (Good Agricultural Practices/GAP).</li>\n<li>Regulasi dan kebijakan terkait penggunaan bibit durian, khususnya apabila varietas yang digunakan berasal dari luar Provinsi Aceh maupun impor, termasuk ketentuan perizinan, karantina, dan sertifikasi bibit.</li>\n<li>Arahan terkait perlindungan varietas lokal, biosekuriti, serta potensi dampak terhadap ekosistem dan komoditas pertanian setempat.</li>\n<li>Ketentuan lain yang dianggap perlu, termasuk aspek pembinaan, pengawasan, serta peluang sinergi program antara PT PEMA (Perseroda) dan Distanbun Provinsi Aceh.</li>\n</ol>\n<p>Besar harapan kami agar Distanbun Provinsi Aceh dapat memberikan arahan awal sebagai dasar bagi PT PEMA (Perseroda) dalam menyusun perencanaan bisnis, kajian teknis, serta kepatuhan terhadap ketentuan peraturan perundang-undangan yang berlaku.&nbsp;</p>\n<p>Demikian kami sampaikan atas perhatian dan kerja sama Bapak/Ibu, kami ucapkan terima kasih.</p>', '', 15, '202103032', 'Staf Migas dan EBTKE', '202402093K', 'id', '2026-01-19 04:19:24', '2026-01-19 04:19:24'),
(928, '48/PEMA/I/2026', 'BkMv1lQrYrbEivsSjItmrfp7uG29r7p5r37IvWF6', 'BPJS ketenagakerjaan', 'Permohonan Sertifikat Kepesertaan Badan Usaha', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>&nbsp;pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2026-01-19 05:14:19', '2026-01-19 05:14:19'),
(929, '49/PEMA/I/2026', 'EAzjrNHJwJIx8XheTz8huLnmjulugnl6clvsXQkM', 'Koperasi jasa Karyawan Pema Syariah (KOPIAH)', 'Pemberitahuan terkait tindak lanjut Tenaga Kontrak', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<p>Pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '013', 'id', '2026-01-19 05:27:26', '2026-01-19 05:27:26'),
(930, '50/PEMA/I/2026', 'hENbkH9FBKv5o3PmjT7Nr2cWiP6Arnm2Y12Lk0QL', 'Badan Pengelolaan Keuangan Aceh <br> c.q. Bidang Akuntansi', 'Penyampaian Laporan Keuangan BUMA (Badan Usaha Milik Aceh) Tahun 2025', 1, 'Eks', 'lampiran/2026/50.pdf', '<p>Dengan hormat,</p>\n<p>Sehubungan dengan surat Badan Pengelolaan Keuangan Aceh tanggal 12 Januari 2025 nomor 900.1.3.10/80 perihal Penyampaian Laporan Keuangan&nbsp;BUMA (Badan Usaha Milik Aceh)&nbsp;Tahun 2025.</p>\n<p>Sebagaimana yang tersebut di atas, berikut kami sampaikan Laporan Keuangan PT Pembangunan Aceh (Perseroda) Tahun 2025 (<em>Unaudited</em>).</p>\n<p>Demikianlah yang dapat kami sampaikan agar dapat dipergunakan sebagaimana mestinya, terima kasih.</p>', '', 23, '202101021', 'Staf Kesekretariatan', '013', 'id', '2026-01-19 08:52:37', '2026-01-19 08:52:37'),
(931, '51/PEMA/I/2026', 'k9v1qAmbFKg9onWlzSY5b5ZWk1irIz9y1lAMliCL', 'Dinas Tenaga Kerja Kota Banda Aceh', 'Pencatatan Perjanjian Kerja Waktu Tertentu (PKWT)', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<p>Berdasarkan Pasal 14 ayat (2) Peraturan Pemerintah No. 35 Tahun 2021 Tentang Perjanjian Kerja Waktu&nbsp;Tertentu, Alih Daya Waktu Kerja dan Waktu Istirahat, dan Pemutusan Hubungan Kerja, maka kami yang bertanda<br>tangan di bawah ini:<br>Nama &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Dr.(C).Tgk. H. Muhammad Nur, M.Si<br>Jabatan &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Direktur Umum dan Keuangan<br>Nama Perusahaan &nbsp; &nbsp; &nbsp;: PT Pembangunan Aceh (Perseroda)<br>Alamat Perusahaan &nbsp; &nbsp;: Rumah Budaya, Jl. Tgk. H. Mohd. Daud Beureueh, Kec. Kuta Alam, Kota &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Banda Aceh<br>Dengan ini mengajukan Pencatatan atas Perjanjian Kerja Waktu Tertentu sebagaimana daftar terlampir, untuk di&nbsp;catat pada Dinas Tenaga Kerja Kota Banda Aceh tempat pekerjaan dilaksanakan. Isi Perjanjian Kerja tersebut&nbsp;sesuai dengan ketentuan Perundang-undangan yang berlaku.<br>Berkaitan dengan hal tersebut, bersama ini kami lampirkan dokumen:<br>1. Fotocopy Perjanjian Kerja yang telah ditandatangani para pihak di atas materai (dan asli Perjanjian Kerja &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br>&nbsp; &nbsp; &nbsp; &nbsp;untuk ditunjukkan);<br>2. Rekap nama dan jabatan pekerja/buruh yang menandatangani Perjanjian Kerja;<br>3. Draft Perjanjian Kerja yang dilampirkan dalam permohonan pendaftaran Perjanjian Penyediaan Jasa Pekerja/ &nbsp;&nbsp;<br>&nbsp; &nbsp; &nbsp; &nbsp;Buruh.<br>Demikian Permohonan ini kami ajukan untuk mendapatkan Bukti Pencatatan Perjanjian Kerja Waktu&nbsp;Tertentu, terima kasih.</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '013', 'id', '2026-01-20 07:24:34', '2026-01-21 01:31:48'),
(932, '52/PEMA/I/2026', 'K9hydzsn42Ci1vPPBY9FCktbm9XaO4ciUC983wid', 'The Management of M Energy Asia', 'Price Quotation and Information for Condensate Tank F-6104', 1, 'Eks', 'lampiran/2026/52.pdf', '<p>We refer to our previous discussion regarding the utilization of Condensate Tank F-6104.</p>\n<p>In this regard, we are pleased to submit our price quotation along with the relevant information for Condensate Tank F-6104. The detailed information and commercial terms are provided as attached for your review and consideration.</p>\n<p>Should you require any further clarification or additional information, please do not hesitate to contact us. We look forward to your feedback and to the possibility of further cooperation.</p>\n<p>Thank you for your attention and kind consideration.&nbsp;</p>', '', 15, '202103032', 'Staf Migas dan EBTKE', '011', 'en', '2026-01-20 08:18:34', '2026-01-20 08:18:34'),
(933, '53/PEMA/I/2026', 'OTeiHPscYQwNShop6vQk52BVXLXnd2vy2PoX3zqS', 'BANK SYARIAH INDONESIA KCP LUENG BATA', 'Permohonan Pembukaan Blokir Saldo Rekening', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<p>Sehubungan dengan adanya pemblokiran saldo pada rekening atas nama Sumatera Noble Coffee KSO dengan nomor rekening 9999962634, bersama ini kami mengajukan permohonan agar kiranya pihak PT Bank Syariah Indonesia dapat melakukan pembukaan blokir saldo atas rekening tersebut, agar rekening dimaksud dapat kembali digunakan untuk keperluan transaksi operasional perusahaan.</p>\n<p class=\"isSelectedEnd\">Sebagai bahan pertimbangan, kami siap melengkapi dokumen pendukung yang diperlukan sesuai ketentuan yang berlaku.</p>\n<p>Demikian permohonan ini kami sampaikan. Atas perhatian dan kerja sama Bapak/Ibu, kami ucapkan terima kasih.</p>', '', 11, '202308073K', 'Staf Keuangan', '003', 'id', '2026-01-20 09:14:36', '2026-01-20 09:14:36'),
(934, '54/PEMA/I/2026', 'lu9A9p1zX985ztkQoIneSS7xrombyRZBAM8BRq6y', 'BCA KCP Bursa Efek Jakarta', 'Konfirmasi Bank', 1, 'Eks', 'lampiran/2026/54.pdf', '<p>Dengan Hormat,</p>\n<p><span data-olk-copy-source=\"MessageBody\">Sehubungan dengan audit yang dilakukan oleh Akuntan Publik kami, mohon bantuan Anda untuk mengisi surat konfirmasi di bawah ini, dan mengembalikan langsung kepada Akuntan Publik kami.</span></p>\n<p><span data-olk-copy-source=\"MessageBody\">Demikian kami sampaikan atas perhatian dan kerjasamanya kami ucapkan terima kasih.</span></p>', '', 11, '202308073K', 'Staf Keuangan', '013', 'id', '2026-01-20 09:25:20', '2026-01-20 09:25:20'),
(935, '55/PEMA/I/2026', 'pBQJWABDspNeppqeFGTO50U7R0MMznFWaH44CR3v', 'BANK SYARIAH INDONESIA KCP LUENG BATA', 'Permohonan Pembukaan Blokir Saldo Rekening', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<p>Sehubungan dengan adanya pemblokiran saldo pada rekening atas nama:</p>\n<ol>\n<li>PT Pema Global Servis<br>No. Rekening: 1909999207 (KC Luengbata)<br>No. Rekening: 1909999304 (KC BD Aceh Diponegoro)</li>\n<li>Tridaya Pasifik KSO<br>No. Rekening: 1308888831 ((KCP Luengbata)</li>\n<li>PGS Dinar KSO<br>No. Rekening: 1909997107 (KC Luengbata)</li>\n</ol>\n<p>Bersama ini kami mengajukan permohonan agar kiranya pihak PT Bank Syariah Indonesia dapat melakukan pembukaan blokir saldo atas rekening tersebut, agar rekening dimaksud dapat kembali digunakan untuk keperluan transaksi operasional perusahaan.</p>\n<p>Sebagai bahan pertimbangan, kami siap melengkapi dokumen pendukung yang diperlukan sesuai ketentuan yang berlaku.</p>\n<p>Demikian permohonan ini kami sampaikan. Atas perhatian dan kerja sama Bapak/ Ibu, kami ucapkan terima kasih.</p>\n<p>&nbsp;</p>', '', 11, '202308073K', 'Staf Keuangan', '003', 'id', '2026-01-21 07:50:44', '2026-01-21 07:53:03'),
(936, '56/PEMA/I/2026', 'f9yoVt9epLtLDq07U7wPWBl6QJV2boGUpWCd93q7', 'Kepala Badan Pengelolaan Keuangan Aceh (BPKA)', 'Permohonan Audiensi', 0, 'Eks', 'lampiran/2026/56.pdf', '<p>Dengan Hormat,</p>\n<ol>\n<li>Sehubungan dengan upaya peningkatan nilai manfaat dan pemanfaatan aset daerah secara optimal, bersama ini kami dari PT Pembangunan Aceh (Perseroda) bermaksud mengajukan permohonan audiensi dengan Badan Pengelolaan Keuangan Aceh (BPKA).</li>\n<li>Audiensi ini kami maksudkan sebagai forum diskusi dan koordinasi awal untuk menyampaikan gagasan, pandangan, serta potensi kerja sama terkait optimalisasi aset, baik dari aspek pemanfaatan, pengelolaan, maupun pengembangan aset agar dapat memberikan nilai tambah ekonomi dan mendukung pendapatan daerah.</li>\n<li>Kami mengusulkan pelaksanaan audiensi tersebut dapat dilaksanakan pada:&nbsp;<br>Hari / Tanggal&nbsp; &nbsp;: Jum\'at / 30 Januari 2026 <br>Waktu&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : 10.00 WIB - Selesai<br>Tempat&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Menyesuaikan dengan ketentuan BPKA&nbsp;</li>\n<li>Namun demikian, kami sangat terbuka apabila waktu dan tempat audiensi tersebut menyesuaikan dengan ketersediaan dan agenda Bapak/Ibu.</li>\n<li>Kami berharap melalui audiensi ini dapat diperoleh arahan, masukan, serta pandangan strategis dari BPKA terkait kebijakan, mekanisme dan peluang optimalisasi aset yang dapat disinergikan ke depan sesuai dengan ketentuan peraturan perundang-undangan yang berlaku.</li>\n</ol>\n<p>Demikian permohonan ini kami sampaikan. Besar harapan kami agar permohonan audiensi ini dapat difasilitasi. Atas perhatian dan kerja sama Bapak/Ibu, kami ucapkan terima kasih.</p>', '', 15, '202103032', 'Staf Migas dan EBTKE', '011', 'id', '2026-01-21 09:30:48', '2026-01-27 01:11:50'),
(937, '57/PEMA/I/2026', 'pZZ76ukZv0znjRm2f93IekxfFI3iIDX4GKORC2V6', 'Citaglobal Berhad', 'Konfirmasi Audiensi Citaglobal dengan Pemerintah Aceh', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<p>Ambil nomor</p>', '', 16, '202106034', 'Staf Teknikal dan Operasi (Migas dan EBTKE)', '003', 'id', '2026-01-22 09:22:58', '2026-01-22 09:22:58'),
(938, '58/PEMA/I/2026', 'BticIzdrarvVdCH7OXmNHMLWBXBB2YKo2PAjCa1S', 'Bank Syariah Indonesia', 'Pembayaran Gaji Karyawan Bulan Januari 2026', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>Pengambilan Nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2026-01-23 01:37:31', '2026-01-23 01:37:31'),
(939, '59/PEMA/I/2026', 'MNUa8CoTvPTRsmjzRPpliDRakC03yaGWSzwzGTDE', 'Bank Aceh Syariah', 'Pembayaran Gaji Karyawan Bulan Januari 2026', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2026-01-23 01:38:02', '2026-01-23 01:38:02'),
(940, '60/PEMA/I/2026', 'r2PFTYuoEoqGmzmvrMmhfeaFgoqd7nU3q96ZKL2o', 'Bank Syariah Nasional', 'Pembayaran Gaji Karyawan Bulan Januari 2026', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2026-01-23 01:38:37', '2026-01-23 01:38:37'),
(941, '61/PEMA/I/2026', 'eDK7SyWgl6OkeyyAid9dgIDob6LpAPElUBruMCxv', 'Lembaga Manajemen Aset Negara (LMAN)', 'Rencana Kerja Sama Pemanfaatan Lahan', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<p>Sehubungan dengan audiensi antara PT Pembangunan Aceh (Perseroda) dengan LMAN pada hari Jum\'at tanggal 23 Januari 2026 terkait Pembahasan Rencana Investasi pada Lahan di Kawasan Ekonomi Khusus (KEK) Arun Lhokseumawe, untuk itu kami meminta kepada saudara terkait informasi mengenai:</p>\n<ol>\n<li>Lahan yang tersedia untuk dilakukan kerja sama beserta dengan zona peruntukan</li>\n<li>Skema kerja sama yang ditawarkan berdasarkan materi paparan</li>\n<li>Infrastruktur pada lahan yang tersedia untuk dimanfaatkan/disewakan</li>\n</ol>\n<p>Demikiaan yang dapat kami sampaikan, atas perhatian dan kerjasamanya kami ucapkan terima kasih.</p>', '', 15, '202103032', 'Staf Migas dan EBTKE', '011', 'id', '2026-01-23 09:59:21', '2026-01-23 09:59:21'),
(942, '62/PEMA/I/2026', 'zHWB1HaT9Q5ihX7arOEuSVcvEh5BBIG9w7U9Rxz2', 'Dewan Komisaris PT Pembangunan Aceh (Perseroda)', 'Rapat Penyampaian Rencana Kerja dan Anggaran Perusahaan (RKAP) Tahun 2026 PT Pembangunan Aceh (Perseroda)', 0, 'Eks', NULL, '<p>Dengan hormat,</p>\n<ol>\n<li>Sehubungan dengan telah disusunnya Rencana Kerja dan Anggaran Perusahaan (RKAP) Tahun 2026 PT Pembangunan Aceh (Perseroda), kami mengundang Dewan Komisaris untuk dapat hadir pada :\n<table style=\"border-collapse: collapse; width: 100%; border: 0px;\">\n<tbody>\n<tr>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 32.1429%;\">Hari/Tanggal</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.00348%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 65.8537%;\">Kamis, 05 Februari 2026</td>\n</tr>\n<tr>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 32.1429%;\">Pukul</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.00348%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 65.8537%;\">12.00 WIB</td>\n</tr>\n<tr>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 32.1429%;\">Tempat</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.00348%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 65.8537%;\">Ruang Rapat PT PEMA</td>\n</tr>\n<tr>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 32.1429%;\">Agenda</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.00348%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 65.8537%;\">Rapat Penyampaian Rencana Kerja dan Anggaran Perusahaan (RKAP) Tahun 2026 PT Pembangunan Aceh (Perseroda) dan hal-hal lainnya yang dianggap perlu</td>\n</tr>\n</tbody>\n</table>\n</li>\n<li>Adapun rapat ini bertujuan untuk menyampaikan dan membahas secara detail rencana kerja serta&nbsp;anggaran perusahaan yang akan dilaksanakan pada tahun mendatang.</li>\n</ol>\n<p>Demikianlah undangan ini kami sampaikan, atas kehadirannya kami ucapkan terima kasih.</p>', '', 23, '202101021', 'Staf Kesekretariatan', '0001', 'id', '2026-01-23 09:59:34', '2026-02-03 03:26:21'),
(943, '63/PEMA/I/2026', 'wfo4lFQKpVsuYHeA2ryYz4J0phFtoOOl5H7RxFcQ', 'Direktur Pelaksana <br> Aceh Carbon Pte. Ltd.', 'Usulan Nama Pengurus dan Pelaksanaan RUPS PT Pema Aceh Carbon', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<ol>\n<li>Merujuk pada:\n<ol>\n<li>Perjanjian Usaha Patungan PT Pembangunan Aceh dengan Carbon Aceh Pte. Ltd. tanggal 27 September 2022, dan</li>\n<li>Akta Pendirian PT Pema Aceh Carbon Nomor 17 tanggal 8 November 2022. &nbsp;</li>\n</ol>\n</li>\n<li>Berdasarkan Perjanjian Usaha Patungan sebagaimana disebut pada butir 1 huruf (a), khususnya Pasal 5.4(b) dan Pasal 5.32(c), diatur bahwa PT Pembangunan Aceh (Perseroda) memiliki hak untuk mencalonkan 1 (satu) anggota Direksi dan 1 (satu) Presiden Komisaris pada PT Pema Aceh Carbon. &nbsp;</li>\n<li>Selanjutnya, sesuai Akta Pendirian PT Pema Aceh Carbon Nomor 17 tanggal 8 November 2022, khususnya Pasal 11 ayat (6) dan Pasal 14 ayat (4), diatur bahwa masa jabatan Direksi dan Dewan Komisaris adalah selama 3 (tiga) tahun sejak tanggal pengangkatan melalui RUPS, sehingga masa jabatan telah berakhir pada tanggal 8 November 2025. &nbsp;</li>\n<li>Berdasarkan hal-hal tersebut di atas, bersama ini kami sampaikan usulan nama-nama perwakilan dari PT Pembangunan Aceh (Perseroda) sebagai pengurus PT Pema Aceh Carbon (PAC) untuk satu periode jabatan atau sampai dengan RUPS memutuskan lain, dengan rincian sebagai berikut:&nbsp;\n<table style=\"border-collapse: collapse; width: 100%; height: 144.688px;\" border=\"1\"><colgroup><col style=\"width: 6.86813%;\"><col style=\"width: 29.5788%;\"><col style=\"width: 28.022%;\"><col style=\"width: 35.5311%;\"></colgroup>\n<tbody>\n<tr style=\"height: 19px;\">\n<td rowspan=\"2\"><strong>No</strong></td>\n<td rowspan=\"2\"><strong>Jabatan</strong></td>\n<td style=\"text-align: center;\" colspan=\"2\"><strong>Nama Perwakilan Pema</strong></td>\n</tr>\n<tr style=\"height: 19px;\">\n<td><strong>Sebelumnya</strong></td>\n<td><strong>Usulan</strong></td>\n</tr>\n<tr style=\"height: 19px;\">\n<td>1</td>\n<td>Presiden Komisaris</td>\n<td>Mahdinur</td>\n<td>Kennedi</td>\n</tr>\n<tr style=\"height: 19px;\">\n<td>2</td>\n<td>Direktur</td>\n<td>Teuku Kamaruzzaman</td>\n<td>Sofyan Dawood</td>\n</tr>\n</tbody>\n</table>\n</li>\n<li>Sehubungan dengan hal tersebut, kami harapkan PT PAC dapat segera melaksanakan RUPS dengan mekanisme sirkuler/offline dengan waktu yang disepakati oleh para Pemegang Saham PT PAC. &nbsp;</li>\n</ol>\n<p>Demikian kami sampaikan, atas perhatiannya kami ucapkan terima kasih.&nbsp;</p>\n<p>&nbsp;</p>', '', 18, '202106034', 'Staf Teknikal dan Operasi (Migas dan EBTKE)', '0001', 'id', '2026-01-23 14:46:42', '2026-01-27 02:09:27'),
(945, '65/PEMA/I/2026', 'aptI9zl5WakS0tjlNMuXxWiIDM52N0d7SbXJKcjK', 'BPJS Kota Banda Aceh', 'Penonaktifan Peserta BPJS', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>Pengambilan Nomor Surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2026-01-26 03:44:04', '2026-01-26 03:44:04'),
(946, '66/PEMA/I/2026', 'i0GjKJfmStFO2oqBQtK6wQumDwGGryoeCWle9Lqg', '1. Inspektur Aceh <br> 2. Kepala Badan Pengelolaan Keuangan Aceh <br> 3. Kepala Dinas Perindustrian dan Perdagangan Aceh <br> 4. Kepala Biro Perekonomian Setda Aceh <br> 5. Kepala Biro Hukum Setda Aceh <br> 6. Kepala Kantor Wilayah DJKN Aceh <br> 7.Kepala BPKP Perwakilan Aceh', 'Undangan FGD terkait Tindak Lanjut Laporan Hasil Pemeriksaan (LHP) Itjen Kemendagri terhadap KIA Ladong.', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<ol>\n<li>Merujuk pada:\n<ol style=\"list-style-type: lower-alpha;\">\n<li>Kerja Sama Pemanfaatan (KSP) antara Pemerintah Aceh dan PT Pembangunan Aceh Nomor 47/PKS/2020 dan 005/PEMA-PKS/III/2020 Tanggal 12 Maret 2020 Tentang Pemanfaatan Tanah dan Bangunan Beserta Fasilitas Pendukung di Kawasan Industri Aceh (KIA) Ladong.</li>\n<li>Laporan Hasil Pemeriksaan Penyelenggaraan Pemerintahan Daerah Pada Pemerintah Provinsi Aceh Tahun Anggaran 2025.</li>\n</ol>\n</li>\n<li>Berkenaan dengan hal tersebut di atas, bersama ini kami mengundang Bapak/Ibu untuk dapat hadir pada:&nbsp;\n<table style=\"border-collapse: collapse; width: 100%; border: 0px;\">\n<tbody>\n<tr>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 23.324%;\">Hari / Tanggal</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.3743%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 74.3017%;\">Kamis, 29 Januari 2026</td>\n</tr>\n<tr>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 23.324%;\">Waktu</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.3743%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 74.3017%;\">14.30 WIB - Selesai</td>\n</tr>\n<tr>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 23.324%;\">Tempat</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.3743%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 74.3017%;\">Kantor PT Pembangunan Aceh (PEMA)</td>\n</tr>\n<tr>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 23.324%;\">Agenda</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 2.3743%;\">:</td>\n<td style=\"vertical-align: top; border: 0px; line-height: 1.2; width: 74.3017%;\">Focus Group Discussion (FGD) terkait Tindak Lanjut Laporan Hasil Pemeriksaan (LHP) Itjen Kemendagri dan Addendum KSP KIA Ladong</td>\n</tr>\n</tbody>\n</table>\n</li>\n</ol>\n<p>Demikian kami sampaikan atas perhatian dan Kerjasama yang baik kami ucapkan terimakasih.</p>', '', 18, '202106034', 'Staf Teknikal dan Operasi (Migas dan EBTKE)', '003', 'id', '2026-01-26 08:55:58', '2026-01-26 08:55:58'),
(947, '67/PEMA/I/2026', 'U0qU2glFBfX0FE1NkQj789R5aB5FaDjqln0NHPCi', 'SIMREK PKH', 'Surat Pernyataan sebagai Penanggungjawab Akun Perusahaan pada Aplikasi SIMREK PKH', 0, 'Eks', NULL, '<p>Dengan Hormat,</p>\n<p>Ambil nomor</p>', '', 16, '202106034', 'Staf Teknikal dan Operasi (Migas dan EBTKE)', '003', 'id', '2026-01-27 02:15:03', '2026-01-27 02:15:03'),
