(979, '99/PEMA/II/2026', 'wd0thQVQK61iwd69UWkJ27S5DgkHavQ8RKP9t4k1', 'Bank Syariah Indonesia', 'pembayaran pesangon karyawan', 0, 'Eks', NULL, '<p>Dengan Hormat</p>\n<p>pengambilan nomor surat</p>', '', 22, '202402039P', 'Staf Sumber Daya Manusia', '202202042', 'id', '2026-02-03 10:43:48', '2026-02-03 10:43:48'),
